+// RF-005: anular una factura emitida con motivo obligatorio. Devuelve una factura nueva en estado "anulada";
+// la original no cambia (ADR-002). Emitir la factura correctiva es un paso aparte.
+export function anularFactura(factura, motivo) {
+  if (factura?.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  if (typeof motivo !== "string" || motivo.trim() === "") throw new Error("La anulación requiere un motivo");
+  return Object.freeze({ ...factura, estado: "anulada", motivo: motivo.trim() });
